import{_ as s,o as a,c as t,a7 as i}from"./chunks/framework.C4ZIv4ii.js";const k=JSON.parse('{"title":"Documentation scripts","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/README.md","filePath":"scripts/README.md","lastUpdated":1791833165000}'),o={name:"scripts/README.md"};function n(h,e,r,d,c,l){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="documentation-scripts" tabindex="-1">Documentation scripts <a class="header-anchor" href="#documentation-scripts" aria-label="Permalink to &quot;Documentation scripts&quot;">​</a></h1><h2 id="screenshots-mjs" tabindex="-1"><code>screenshots.mjs</code> <a class="header-anchor" href="#screenshots-mjs" aria-label="Permalink to &quot;\`screenshots.mjs\`&quot;">​</a></h2><p>Regenerates every image under <code>docs/public/screenshots/</code> from the live demo at <a href="https://demo.falconcms.com" target="_blank" rel="noreferrer">https://demo.falconcms.com</a>. Those images are what the README and the documentation pages embed, so this is how they stay current after a UI change.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:screenshots</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # all targets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:screenshots</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orders</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # just these two</span></span></code></pre></div><p>The first run installs Playwright and its Chromium build with <code>--no-save</code>. That is deliberate: the docs deploy workflow runs <code>npm install</code> in this directory, and a saved <code>playwright</code> dependency would make every deploy download a browser it never uses.</p><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><p>Every target is captured at a 1440×900 viewport with <code>deviceScaleFactor: 2</code>, then downscaled to 1600px wide and encoded as WebP — by Chromium itself, so the script needs no native image library. The whole set is about 2 MB.</p><p>Because the viewport, the device scale and the settle delay are the same for all of them, re-running the script replaces the set consistently rather than leaving one page shot at a different width than its neighbours.</p><h3 id="when-a-capture-comes-back-wrong" tabindex="-1">When a capture comes back wrong <a class="header-anchor" href="#when-a-capture-comes-back-wrong" aria-label="Permalink to &quot;When a capture comes back wrong&quot;">​</a></h3><ul><li><strong>Sign-in fails.</strong> The demo prints its current credentials on the login page. Pass a new one with <code>DEMO_PASSWORD=… npm run docs:screenshots</code>. The script stops on a failed sign-in instead of retrying, because the demo locks an account after repeated failures.</li><li><strong>The builder captures are empty.</strong> They address a specific page by id (<code>BUILDER_PAGE_ID</code> at the top of the script). The demo is reseeded from time to time; when it is, pick a new page from <code>/admin/pages</code> and update the constant.</li><li><strong>A panel did not open.</strong> The builder targets drive the UI through <code>steps</code>, which clicks real selectors — <code>.topbar-icon[title=&quot;Responsive&quot;]</code> and the navigator nodes. A markup change in the builder is the usual cause.</li></ul><h3 id="pointing-it-at-something-else" tabindex="-1">Pointing it at something else <a class="header-anchor" href="#pointing-it-at-something-else" aria-label="Permalink to &quot;Pointing it at something else&quot;">​</a></h3><p><code>DEMO_URL</code>, <code>DEMO_EMAIL</code> and <code>DEMO_PASSWORD</code> override the demo. A local site works too:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEMO_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://falcon.test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEMO_EMAIL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin@example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEMO_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">secret</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:screenshots</span></span></code></pre></div><p>Prefer the public demo for anything that ships. It carries demo content that is meant to be seen, and it is the same site a reader can click through for themselves.</p><h2 id="screenshots-this-script-does-not-take" tabindex="-1">Screenshots this script does not take <a class="header-anchor" href="#screenshots-this-script-does-not-take" aria-label="Permalink to &quot;Screenshots this script does not take&quot;">​</a></h2><p>The SEO, Search Console, Web Vitals and shop-pages images (<code>seo-*.webp</code>, <code>bulk-seo.webp</code>, <code>editor-seo-*.webp</code>, <code>editor-search-console.webp</code>, <code>search-console*.webp</code>, <code>web-vitals.webp</code>, <code>customizer-performance.webp</code>, <code>integrations-cloudflare.webp</code>, <code>media-avif.webp</code>, <code>shop-pages.webp</code>) were taken from a development site with the same capture settings (1440×900 at 2×, downscaled to 1600px WebP at 0.92). The demo cannot produce them: it is read-only, so the editor&#39;s keyword and search-demand requests are refused, and it has no Search Console connection or visitor speed data. Re-take them on a site that has.</p>`,16)])])}const g=s(o,[["render",n]]);export{k as __pageData,g as default};
